 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Read the slanted color bands by their r-c offset, then tile that cycle
    # as diagonal stripes in the output.
    bands = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                bands[r-c] = v
    offsets = sorted(bands)
    cycle = [bands[k] for k in offsets]
    return [[cycle[(r+c) % len(cycle)] for c in range(w)] for r in range(h)]
